import {WORLDS,COLORS,TYPES,MATERIALS,number,esc,safeUrl,joinResearch,getLimits,filterRows,csv,comparisonRows} from './data.mjs';
const paths={orbit:'M21 12a9 9 0 1 1-9-9M3 20 20 3M16 3h5v5',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M4 19V5m0 14h17M8 15v-4m5 4V7m5 8V3',layers:'m12 3 9 5-9 5-9-5 9-5m-9 9 9 5 9-5M3 16l9 5 9-5',book:'M3 4h6q3 0 3 3v14q0-3-3-3H3V4m18 0h-6q-3 0-3 3v14q0-3 3-3h6V4',info:'M12 10v7m0-10v.1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',download:'M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16m-6-6 6 6-6 6',external:'M14 3h7v7m-10 3L21 3M10 3H3v18h18v-7',flame:'M13 2c1 8-8 7-8 14a7 7 0 0 0 14 0c0-4-2-7-5-9 1 5-4 5-1-5',pause:'M8 5v14M16 5v14',play:'m8 4 12 8-12 8V4',reset:'M3 10a9 9 0 1 1 1 8M3 4v6h6',database:'M21 5c0 2-4 3-9 3S3 7 3 5s4-3 9-3 9 1 9 3M3 5v14c0 2 4 3 9 3s9-1 9-3V5M3 12c0 2 4 3 9 3s9-1 9-3'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.orbit}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const view=document.querySelector('#view'),dialog=document.querySelector('#detail-dialog');
const state={view:'overview',world:'Earth',material:'Ultem 1000',query:'',filterWorld:'All',filterMaterial:'All',filterKind:'All',page:0,sourceQuery:'',sourceType:'All',sourcePage:0};
const worldInfo={Moon:{title:'Lunar gravity',g:'0.16',sub:'Nominal lunar category',name:'The Moon',caption:'A different gravity. A different combustion story.'},Mars:{title:'Martian gravity',g:'0.38',sub:'Nominal Martian category',name:'Mars',caption:'Compare the evidence before the next frontier.'},Earth:{title:'Earth gravity',g:'1.00',sub:'Normal-gravity reference',name:'Earth',caption:'The familiar baseline. Not the whole picture.'},Microgravity:{title:'Microgravity',g:'≈ 0',sub:'Free-fall environment',name:'Microgravity',caption:'When buoyancy fades, other forces take the lead.'}};
let bundle,rows,globe,renderSequence=0,toastTimer;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function download(content,name,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Export ready');}
function metricStrip(){return `<section class="metric-strip" aria-label="BigQuery archive totals">${[['chart',bundle.tableCounts.measurements,'Reported results','EXTRACTED'],['orbit',bundle.tableCounts.experiments,'Experiment contexts','CATALOGUED'],['book',bundle.tableCounts.sources,'Research sources','INDEXED'],['database',bundle.tableCounts.files,'File catalogue entries','METADATA']].map(([i,n,title,note])=>`<div class="metric-item"><span class="metric-symbol">${icon(i)}</span><div><strong>${number(n,0)}</strong><small>${title}</small></div><span class="metric-note">${note}</span></div>`).join('')}</section>`}
function materialPanel(){return `<section class="panel material-panel"><div class="panel-head">Materials<span class="tiny">2012 comparison</span></div><div class="material-list">${MATERIALS.map((m,i)=>`<button data-material="${esc(m)}" class="${state.material===m?'active':''}" aria-pressed="${state.material===m}"><span class="sample-mark">${['PEI','PET','AR'][i]}</span>${esc(m)}<span class="count">${rows.filter(r=>r.experiment.material===m).length}</span></button>`).join('')}</div></section>`}
function typeMix(){return `<section class="panel mix-panel"><div class="label">EVIDENCE COMPOSITION</div><div class="segmented-bar">${Object.entries(TYPES).map(([key,t])=>`<span style="flex:${rows.filter(r=>r.evidence_type===key).length};background:${t.color}" title="${t.name}: ${rows.filter(r=>r.evidence_type===key).length}"></span>`).join('')}</div><div class="mix-labels">${Object.entries(TYPES).map(([key,t])=>`<span><i style="background:${t.color}"></i>${t.name} ${rows.filter(r=>r.evidence_type===key).length}</span>`).join('')}</div></section>`}
function chart(large=false){const entries=comparisonRows(rows,state.material),w=600,h=large?300:170,left=42,right=20,top=22,bottom=32,plotH=h-top-bottom,slot=(w-left-right)/4;const y=v=>top+plotH-(Number(v)/30)*plotH;return `<svg class="comparison-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Reported oxygen limits for ${esc(state.material)}. Separate observations, not an interpolated prediction.">${[0,10,20,30].map(v=>`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#29404a" stroke-dasharray="3 5"/><text x="${left-10}" y="${y(v)+3}" fill="#819ca9" font-size="9" text-anchor="end">${v}</text>`).join('')}<text x="10" y="12" fill="#8aa7b4" font-size="8">O₂ %</text>${entries.map(({world,uloi,moc},i)=>{const cx=left+slot*(i+.5);return `<g>${[[uloi,-14,'#b9f3d8'],[moc,12,'#78b6cd']].map(([r,off,c])=>r?`<rect x="${cx+off-8}" y="${y(r.value)}" width="16" height="${y(0)-y(r.value)}" fill="${c}" fill-opacity=".16" rx="2"/><line x1="${cx+off}" x2="${cx+off}" y1="${y(0)}" y2="${y(r.value)}" stroke="${c}" stroke-opacity=".5"/><circle cx="${cx+off}" cy="${y(r.value)}" r="3.5" fill="${c}"/><text x="${cx+off}" y="${y(r.value)-10}" fill="${c}" font-size="${large?11:9}" text-anchor="middle">${number(r.value)}</text>`:'').join('')}<text x="${cx}" y="${h-12}" fill="${COLORS[world]}" font-size="10" text-anchor="middle">${world==='Microgravity'?'Microgravity':world}</text></g>`}).join('')}</svg>`}
function chartPanel(large=false){return `<section class="panel chart-panel"><div class="panel-head"><span>Oxygen limits across gravity</span><span class="tiny">${esc(state.material)}</span></div><div class="legend"><span><i style="background:#b9f3d8"></i>ULOI / ULOI*</span><span><i style="background:#78b6cd"></i>MOC / MOC*</span></div>${chart(large)}<p class="chart-note">Starred low-g limits use short-duration flame survival or extinction. Earth tests use different burn criteria. <a href="https://ntrs.nasa.gov/citations/20130010991" target="_blank" rel="noopener noreferrer">Table I, p. 6 ↗</a></p></section>`}
function overview(){const info=worldInfo[state.world],limits=getLimits(rows,state.material,state.world),exp=limits.uloi?.experiment,contextCount=bundle.experiments.filter(e=>e.gravity_label===state.world).length;const sample=rows.filter(r=>r.experiment.gravity_label===state.world&&r.experiment.material===state.material).slice(0,3);return `${metricStrip()}<div class="mission-grid"><div class="left-stack"><section class="panel context-panel"><div class="label">SELECTED ENVIRONMENT</div><div class="context-title"><h2>${info.title}</h2><span class="tiny-orbit" aria-hidden="true"></span></div><div class="gravity-number">${info.g}<span>g</span></div><div class="subtle">${info.sub} · experiment context</div><div class="world-picker" aria-label="Gravity context">${['Earth','Microgravity','Moon','Mars'].map(w=>`<button data-world="${w}" class="${state.world===w?'active':''}" aria-pressed="${state.world===w}" aria-label="${w}">${w==='Microgravity'?'µg':w}</button>`).join('')}</div></section>${materialPanel()}${typeMix()}</div><section class="space-panel" aria-label="Interactive planet context"><div id="globe" aria-label="Drag to rotate the decorative planet" role="img"><div class="globe-fallback"></div></div><div class="space-top"><span class="space-label"><i></i>GRAVITY CONTEXT</span><span class="space-reference">SORAINE / 0${WORLDS.indexOf(state.world)+1}</span></div><div class="orbit-callout"><small>${state.world.toUpperCase()} RESEARCH</small><strong>${contextCount} experiment contexts</strong></div><div class="orbit-callout secondary"><small>SELECTED MATERIAL</small><strong>${esc(state.material)}</strong></div><div class="space-caption"><div class="eyebrow">FLAME IN FREEFALL</div><h2>${info.name}</h2><p>${info.caption}</p></div><div class="space-foot"><span>Illustrative view · drag to rotate</span><div class="globe-actions"><button id="zoom-in" aria-label="Zoom in" title="Zoom in">+</button><button id="zoom-out" aria-label="Zoom out" title="Zoom out">−</button><button id="rotate-toggle" aria-label="Pause rotation" title="Pause rotation">${icon('pause')}</button><button id="reset-globe" aria-label="Reset globe" title="Reset globe">${icon('reset')}</button></div></div></section><div class="right-stack"><section class="panel focus-panel"><div class="label">MATERIAL SPOTLIGHT</div><div class="focus-heading"><h2>${esc(state.material)}</h2><span class="chip">PUBLISHED</span></div><p class="focus-sub">${esc(exp?.conditions||'Published sample')} · ${state.world}</p><div class="limit-pair">${[[limits.uloi,'ULOI'],[limits.moc,'MOC']].map(([r,label])=>`<div><div class="label">${r?.metric||label}</div><strong>${r?number(r.value):'—'}<small>%</small></strong><div class="subtle">oxygen, molar</div></div>`).join('')}</div><div class="condition-list"><div><span>Test pressure</span><b>${number(exp?.pressure_kpa)} kPa</b></div><div><span>Material form</span><b>${esc(exp?.conditions||'See source')}</b></div><div><span>Source</span><b>NASA NTRS · Table I</b></div></div><button class="primary-btn wide" data-view="compare">Compare across gravity ${icon('arrow')}</button></section><section class="panel note-panel"><div class="note-title">${icon('info')}Read the limits</div><p>These values describe tests of ignited samples. They do not certify a habitat as fire-safe or predict the chance of a fire.</p><button class="text-link" data-record="${esc(limits.uloi?.measurement_id)}">Explore the test conditions ${icon('external')}</button></section></div></div><div class="lower-grid">${chartPanel()}<section class="panel"><div class="panel-head">Selected evidence<span class="tiny">${state.world} / ${esc(state.material)}</span></div><table class="mini-table"><thead><tr><th>Record</th><th>Metric</th><th>Reported value</th><th></th></tr></thead><tbody>${sample.map(r=>`<tr data-record="${r.measurement_id}" tabindex="0" role="button" aria-label="Open ${r.measurement_id}"><td><span class="row-dot" style="background:${r.kind.color}"></span>${r.measurement_id}</td><td>${metricName(r.metric)}</td><td class="mono">${number(r.value)} ${r.unit==='O2 percentage points'?'pp':r.unit==='O2 molar percent'?'%':esc(r.unit)}</td><td>↗</td></tr>`).join('')}</tbody></table><div class="panel-footer"><span>Trace every result to its source.</span><button data-view="evidence">All ${bundle.measurements.length} results →</button></div></section></div>`}
function metricName(metric){return ({reported_delta_O2_vs_1g:'Δ oxygen vs. Earth',flame_base_speed_fit:'Flame-base speed (fit)',flame_tip_speed_fit:'Flame-tip speed (fit)',flame_base_speed_reported:'Flame-base speed',lunar_compensation_delta_at_assumed_35_cm_s:'Lunar compensation at 35 cm/s',O2_vs_flow_best_fit_slope:'O₂–flow slope (best fit)',O2_vs_flow_95pct_conservative_slope:'O₂–flow slope (conservative)'})[metric]||esc(metric)}
function compare(){const selected=getLimits(rows,state.material,'Moon').uloi;return `<div class="view-title-row"><div><div class="eyebrow">MATERIAL COMPARISON</div><h2>One material. Four environments.</h2><p>Follow the published oxygen limits across gravity, with the original test conditions kept in view.</p></div><button class="export-btn" id="export-comparison">${icon('download')}Export comparison</button></div><div class="compare-layout"><div class="left-stack">${materialPanel()}<section class="panel note-panel"><div class="note-title">${icon('info')}Compare with context</div><p>${esc(selected.experiment.conditions)}<br>${number(selected.experiment.pressure_kpa)} kPa absolute (${number(selected.experiment.pressure_psia)} psia)</p><p>These are terrestrial experiments that reproduce gravity conditions. They are not fires measured on the lunar or Martian surface.</p></section>${typeMix()}</div><div class="compare-main"><div class="compare-card-row">${comparisonRows(rows,state.material).map(({world,uloi,moc})=>`<button class="panel compare-world" data-record="${uloi.measurement_id}" aria-label="Inspect ${world} ${state.material} ULOI"><h3 style="color:${COLORS[world]}">${world}</h3><div class="world-g">${worldInfo[world].g} g · nominal category</div><strong style="color:${COLORS[world]}">${number(uloi.value)}<small>%</small></strong><div class="compare-metric">${uloi.metric} · oxygen</div><div class="source-hint">${moc.metric}: ${number(moc.value)}% <span aria-hidden="true">↗</span></div></button>`).join('')}</div>${chartPanel(true)}<div class="science-note"><h3>What this comparison can tell us</h3><p>The same material has different reported oxygen limits in different gravity conditions. The starred low-gravity values describe flame survival or extinction during short drop tests; the Earth values use different burn criteria. Read them alongside the methods, not as interchangeable safety thresholds. No curve or predicted intermediate-gravity value is inferred here.</p><a href="${safeUrl(selected.source.url)}" target="_blank" rel="noopener noreferrer">Olson & Ferkul · 2012 · Table I, PDF page 6 ↗</a></div></div></div>`}
function option(value,label,current){return `<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`}
function evidence(){return `<div class="view-title-row"><div><div class="eyebrow">THE RESEARCH, IN DETAIL</div><h2>Evidence explorer</h2><p>Filter the reported results, inspect the test context, and open the original source.</p></div><button class="export-btn" id="export-filtered">${icon('download')}Export filtered CSV</button></div><div class="filterbar"><label>${icon('search')}<input id="record-search" value="${esc(state.query)}" placeholder="Material, metric, source…" aria-label="Search evidence"></label><label>Gravity<select id="world-filter" aria-label="Filter gravity">${['All',...WORLDS,'Earth-to-Moon model'].map(v=>option(v,v==='All'?'All environments':v,state.filterWorld)).join('')}</select></label><label>Material<select id="material-filter" aria-label="Filter material">${['All',...new Set(rows.map(r=>r.experiment.material))].map(v=>option(v,v==='All'?'All materials':v,state.filterMaterial)).join('')}</select></label><label>Type<select id="kind-filter" aria-label="Filter evidence type">${option('All','All evidence',state.filterKind)}${Object.entries(TYPES).map(([v,t])=>option(v,t.name,state.filterKind)).join('')}</select></label><button class="clear-filter" id="clear-filters">Reset filters</button></div><section class="panel"><div id="evidence-results"></div></section><p class="browser-legend">Reported results include aggregates, fitted summaries and model-derived values. Row counts are not counts of independent raw trials.</p>`}
function matchingRows(){return filterRows(rows,{query:state.query,world:state.filterWorld,material:state.filterMaterial,kind:state.filterKind})}
function renderEvidenceRows(){const matches=matchingRows(),size=10,pages=Math.max(1,Math.ceil(matches.length/size));state.page=Math.min(state.page,pages-1);document.querySelector('#evidence-results').innerHTML=matches.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Record / material</th><th>Gravity</th><th>Metric</th><th>Value</th><th>Evidence</th><th>Source</th></tr></thead><tbody>${matches.slice(state.page*size,(state.page+1)*size).map(r=>`<tr data-record="${r.measurement_id}" tabindex="0" role="button" aria-label="Inspect ${r.measurement_id}"><td class="table-material">${esc(r.experiment.material)}<span class="table-sub mono">${r.measurement_id}</span></td><td style="color:${COLORS[r.experiment.gravity_label]||'#d9ba88'}">${esc(r.experiment.gravity_label)}</td><td>${metricName(r.metric)}</td><td><span class="number">${number(r.value,8)}</span><span class="table-sub">${esc(r.unit)}</span></td><td><span class="chip ${r.evidence_type.startsWith('model')?'amber':''}" style="color:${r.kind.color}">${r.kind.name}</span></td><td class="mono">${esc(r.source_id.replace('NTRS-',''))}<span class="table-sub">PDF p. ${r.pdf_page||'—'} ↗</span></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${state.page*size+1}–${Math.min((state.page+1)*size,matches.length)} of ${matches.length} results</span><div><button data-page="-1" ${state.page===0?'disabled':''} aria-label="Previous evidence page">←</button><span>${state.page+1} / ${pages}</span><button data-page="1" ${state.page===pages-1?'disabled':''} aria-label="Next evidence page">→</button></div></div>`:`<div class="empty"><strong>No matching results</strong>Try another material or reset the filters.</div>`;}
function sourceView(){return `<div class="view-title-row"><div><div class="eyebrow">SOURCE LIBRARY</div><h2>From the archive to the evidence.</h2><p>${number(bundle.tableCounts.sources,0)} indexed sources. Open the original research and see which documents have extracted results.</p></div></div><div class="pill-row"><span class="stat-pill"><strong>${number(bundle.tableCounts.raw_records,0)}</strong>raw records catalogued</span><span class="stat-pill"><strong>${number(bundle.tableCounts.files,0)}</strong>file metadata entries</span><span class="stat-pill"><strong>${bundle.evidence.length}</strong>supporting evidence statements</span></div><div class="filterbar"><label>${icon('search')}<input id="source-search" value="${esc(state.sourceQuery)}" placeholder="Search titles, source IDs or DOI" aria-label="Search sources"></label><label>Collection<select id="source-type" aria-label="Filter source collection">${['All',...new Set(bundle.sources.map(s=>s.source_type))].map(v=>option(v,v==='All'?'All collections':v.replaceAll('_',' '),state.sourceType)).join('')}</select></label></div><section class="panel"><div id="source-results"></div></section><p class="browser-legend">Catalogue totals describe indexed records. They do not imply that every file was downloaded or that every source supplied quantitative data.</p>`}
function renderSources(){const query=state.sourceQuery.toLowerCase().trim(),matches=bundle.sources.filter(s=>(state.sourceType==='All'||s.source_type===state.sourceType)&&[s.title,s.source_id,s.doi].join(' ').toLowerCase().includes(query));const size=10,pages=Math.max(1,Math.ceil(matches.length/size));state.sourcePage=Math.min(state.sourcePage,pages-1);document.querySelector('#source-results').innerHTML=matches.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Source / title</th><th>Collection</th><th>Year</th><th>Extracted results</th><th></th></tr></thead><tbody>${matches.slice(state.sourcePage*size,(state.sourcePage+1)*size).map(s=>`<tr><td><a class="source-title" href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.source_id)}</a><span class="table-sub mono">${esc(s.source_id)}</span></td><td>${esc(s.source_type.replaceAll('_',' '))}</td><td>${s.publication_date?esc(s.publication_date.slice(0,4)):'—'}</td><td>${rows.filter(r=>r.source_id===s.source_id).length||'—'}</td><td><button class="icon-btn" data-source="${esc(s.source_id)}" aria-label="Details for ${esc(s.title||s.source_id)}">${icon('info')}</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${state.sourcePage*size+1}–${Math.min((state.sourcePage+1)*size,matches.length)} of ${matches.length} sources</span><div><button data-source-page="-1" ${state.sourcePage===0?'disabled':''} aria-label="Previous sources page">←</button><span>${state.sourcePage+1} / ${pages}</span><button data-source-page="1" ${state.sourcePage===pages-1?'disabled':''} aria-label="Next sources page">→</button></div></div>`:`<div class="empty"><strong>No matching sources</strong>Try a shorter search.</div>`;}
async function render(){const seq=++renderSequence;globe?.dispose();globe=null;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false')});view.innerHTML=({overview,evidence,compare,sources:sourceView}[state.view])();view.classList.remove('view-enter');void view.offsetWidth;view.classList.add('view-enter');if(state.view==='evidence')renderEvidenceRows();if(state.view==='sources')renderSources();if(state.view==='overview'){try{const {createGlobe}=await import('./globe.mjs');if(seq!==renderSequence)return;globe=createGlobe(document.querySelector('#globe'),state.world);const button=document.querySelector('#rotate-toggle');button.innerHTML=icon(globe.paused?'play':'pause');button.setAttribute('aria-label',globe.paused?'Resume rotation':'Pause rotation')}catch(e){console.warn('Globe fallback:',e.message)}}}
function navigate(name){if(!['overview','compare','evidence','sources'].includes(name))return;state.view=name;history.replaceState(null,'','#'+name);render()}
function openRecord(id){const r=rows.find(x=>x.measurement_id===id);if(!r)return;const e=r.experiment;const fields=[['Environment',e.gravity_label],['Test pressure',e.pressure_kpa!==null?number(e.pressure_kpa)+' kPa absolute':'Not reported'],['Oxygen',e.oxygen_pct!==null?number(e.oxygen_pct)+' molar %':'Not reported'],['Airflow',e.flow_speed_cm_s!==null?number(e.flow_speed_cm_s)+' cm/s':e.flow_mode||'Not reported'],['Sample',e.conditions||e.material],['Platform',e.platform||'See source'],['Test duration',e.duration_s!==null?number(e.duration_s)+' s':'Not reported'],['Evidence type',r.kind.name]];document.querySelector('#detail-content').innerHTML=`<div class="eyebrow">EVIDENCE / ${esc(r.measurement_id)}</div><h2 id="detail-title">${esc(e.material)}</h2><span class="chip ${r.evidence_type.startsWith('model')?'amber':''}">${r.kind.name}</span><div class="record-value">${number(r.value,8)}<small>${esc(r.unit)}</small></div><div class="subtle">${metricName(r.metric)}</div><div class="detail-grid">${fields.map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><h3>Original source</h3><a class="detail-source" href="${safeUrl(r.source.url)}" target="_blank" rel="noopener noreferrer">${esc(r.source.title)} ↗<br><small>${esc(r.locator)} · PDF page ${r.pdf_page||'not specified'}</small></a><div class="detail-limitation"><h3>How to interpret this result</h3><p>${esc(r.limitation)}</p><p>Reported summary, not an independent raw trial. Uncertainty values are ${r.uncertainty_value===null?'not supplied in this record':esc(r.uncertainty_value+' '+r.uncertainty_unit)}.</p></div><p class="subtle">Gravity basis: ${esc(e.gravity_basis||'See the source methods.')}</p><div class="detail-actions"><button class="export-btn" data-download-record="${r.measurement_id}">${icon('download')}Download record</button></div>`;dialog.showModal();}
function openSource(id){const source=bundle.sources.find(s=>s.source_id===id);const statements=bundle.evidence.filter(e=>e.source_id===id);document.querySelector('#detail-content').innerHTML=`<div class="eyebrow">SOURCE / ${esc(source.source_id)}</div><h2 id="detail-title">${esc(source.title||source.source_id)}</h2><p>${esc(source.source_type.replaceAll('_',' '))}${source.publication_date?' · '+esc(source.publication_date.slice(0,4)):''}</p><a class="detail-source" href="${safeUrl(source.url)}" target="_blank" rel="noopener noreferrer">Open original source ↗</a><h3>${rows.filter(r=>r.source_id===id).length} extracted results · ${statements.length} evidence statements</h3>${statements.map(e=>`<div class="source-excerpt">${esc(e.statement)}<small>${esc(e.locator||'Source text')}${e.pdf_page?' · PDF p. '+e.pdf_page:''}</small>${e.limitation?`<p>${esc(e.limitation)}</p>`:''}</div>`).join('')}<p>Inclusion in the source catalogue does not mean this document contributed a measurement.</p>`;dialog.showModal();}
function showAbout(){document.querySelector('#detail-content').innerHTML=`<div class="eyebrow">TEAM SORAINE / FLAME IN FREEFALL</div><h2 id="detail-title">Built around the evidence.</h2><p>This public dashboard uses research from <strong>flame_in_freefall_2026</strong> from the team's Google BigQuery dataset. Data as of ${new Date(bundle.exportedAt).toLocaleString('en-CA',{timeZone:'UTC'})} UTC. ${bundle.delivery?.mode==='bigquery'?'The server reads BigQuery and caches complete results for five minutes.':bundle.delivery?.mode==='cached-stale'?'Showing the last successful BigQuery refresh while the connection recovers.':'Browsing and filtering use the saved snapshot, not a live database connection.'} File-catalogue totals describe the original export; raw catalogue rows are not exposed.</p><div class="detail-grid"><div><span>Reported results</span><b>${bundle.measurements.length}</b></div><div><span>Experiment contexts</span><b>${bundle.experiments.length}</b></div><div><span>Indexed sources</span><b>${bundle.sources.length}</b></div><div><span>Evidence statements</span><b>${bundle.evidence.length}</b></div></div><h3>Reading the science</h3><p>Published limits, fitted results, derived summaries and model-derived values are labelled separately. Experiment contexts are not independent trials. Pressure and oxygen describe the test environment, not a planet's outdoor atmosphere. The globe and orbit lines are illustrative and do not mark experiment locations. Lunar gravity is grouped nominally; individual test acceleration is described in each record.</p><h3>Credits</h3><ul class="credits-list"><li>Research: Hogan, Ethan and Tony / Team Soraine.</li><li>Visual direction inspired by <a href="https://fuselabcreative.com/our-projects/cyberdefend/" target="_blank" rel="noopener noreferrer">Fuselab Creative's CyberDefend</a>. Original dashboard implementation; reference artwork is not included.</li><li>Moon: <a href="https://svs.gsfc.nasa.gov/4720/" target="_blank" rel="noopener noreferrer">NASA Scientific Visualization Studio, CGI Moon Kit</a>, LRO/LROC color imagery and LOLA elevation-derived surface normals.</li><li>Earth: <a href="https://svs.gsfc.nasa.gov/2915/" target="_blank" rel="noopener noreferrer">NASA/Goddard Scientific Visualization Studio, Blue Marble</a>, Reto Stöckli and NASA Earth Observatory.</li><li>Mars: <a href="https://trek.nasa.gov/mars/" target="_blank" rel="noopener noreferrer">NASA Mars Trek</a>, Viking MDIM 2.1 color mosaic, NASA/JPL/USGS. Earth night lights: <a href="https://svs.gsfc.nasa.gov/2916/" target="_blank" rel="noopener noreferrer">NASA/GSFC and NOAA/NGDC</a>, Mayhew, Simmon, Imhoff and Elvidge.</li><li>Three.js, MIT license. Planet lighting inspired by the <a href="https://threejs.org/examples/webgpu_tsl_earth.html" target="_blank" rel="noopener noreferrer">Three.js Earth example</a>; rendered here in WebGL for broader device support. Lighting and rotation are illustrative, not a current satellite view. NASA Space Apps participant project; no NASA endorsement implied.</li></ul>`;dialog.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button,a,tr[data-record]');if(!b)return;if(b.dataset.view){e.preventDefault();navigate(b.dataset.view)}else if(b.dataset.material){state.material=b.dataset.material;render()}else if(b.dataset.world){state.world=b.dataset.world;render()}else if(b.dataset.record)openRecord(b.dataset.record);else if(b.dataset.source)openSource(b.dataset.source);else if(b.dataset.page){state.page+=Number(b.dataset.page);renderEvidenceRows()}else if(b.dataset.sourcePage){state.sourcePage+=Number(b.dataset.sourcePage);renderSources()}else if(b.dataset.downloadRecord){const r=rows.find(x=>x.measurement_id===b.dataset.downloadRecord);download(JSON.stringify(r,null,2),'soraine-'+r.measurement_id+'.json')}else if(b.id==='about-btn'||b.id==='credits-btn')showAbout();else if(b.id==='export-all')download(JSON.stringify(bundle,null,2),'soraine-bigquery-research.json');else if(b.id==='export-filtered')download(csv(matchingRows()),'soraine-filtered-results.csv','text/csv;charset=utf-8');else if(b.id==='export-comparison')download(csv(rows.filter(r=>r.experiment.material===state.material&&r.evidence_type==='reported_experimental_limit_aggregate')),'soraine-'+state.material.replaceAll(' ','-')+'-comparison.csv','text/csv;charset=utf-8');else if(b.id==='clear-filters'){Object.assign(state,{query:'',filterWorld:'All',filterMaterial:'All',filterKind:'All',page:0});render()}else if(b.id==='zoom-in')globe?.zoom(-.4);else if(b.id==='zoom-out')globe?.zoom(.4);else if(b.id==='reset-globe')globe?.reset();else if(b.id==='rotate-toggle'&&globe){globe.paused=!globe.paused;b.innerHTML=icon(globe.paused?'play':'pause');b.setAttribute('aria-label',globe.paused?'Resume rotation':'Pause rotation');b.title=b.getAttribute('aria-label')}else if(b.classList.contains('dialog-close'))dialog.close();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!dialog.open){e.preventDefault();document.querySelector('#global-search').focus()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-record]')){e.preventDefault();openRecord(e.target.dataset.record)}});
document.addEventListener('input',e=>{if(e.target.id==='record-search'){state.query=e.target.value;state.page=0;renderEvidenceRows()}if(e.target.id==='source-search'){state.sourceQuery=e.target.value;state.sourcePage=0;renderSources()}});
document.addEventListener('change',e=>{const key={'world-filter':'filterWorld','material-filter':'filterMaterial','kind-filter':'filterKind'}[e.target.id];if(key){state[key]=e.target.value;state.page=0;renderEvidenceRows()}if(e.target.id==='source-type'){state.sourceType=e.target.value;state.sourcePage=0;renderSources()}});
document.querySelector('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){state.query=e.target.value;Object.assign(state,{filterWorld:'All',filterMaterial:'All',filterKind:'All',page:0});navigate('evidence');document.querySelector('#record-search').focus();e.target.value=''}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
try{let response=await fetch('./api/research').catch(()=>null);if(!response?.ok)response=await fetch('./data/research.json');if(!response.ok)throw Error('Research data could not be loaded.');bundle=await response.json();document.querySelector('.connection').innerHTML='<i></i> '+(bundle.delivery?.mode==='bigquery'?'BigQuery connected':bundle.delivery?.mode==='cached-stale'?'BigQuery cached':'Saved snapshot');rows=joinResearch(bundle);document.querySelector('#snapshot-date').textContent=(bundle.delivery?.mode==='bigquery'?'Refreshed ':'Snapshot ')+new Date(bundle.exportedAt).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'})+' · '+new Date(bundle.exportedAt).toISOString().slice(11,16)+' UTC';const params=new URLSearchParams(location.search);const worlds={earth:'Earth',moon:'Moon',mars:'Mars',iss:'Microgravity',microgravity:'Microgravity'};if(worlds[params.get('world')?.toLowerCase()])state.world=worlds[params.get('world').toLowerCase()];if(MATERIALS.includes(params.get('material')))state.material=params.get('material');const hash=location.hash.slice(1);if(['overview','compare','evidence','sources'].includes(hash))state.view=hash;await render();}catch(error){view.innerHTML=`<div class="empty"><strong>Research archive unavailable</strong>${esc(error.message)}<p>Reload this page to try again.</p></div>`;document.querySelector('#export-all').disabled=true;document.querySelector('#about-btn').disabled=true;document.querySelector('#credits-btn').disabled=true;console.error(error)}
